import unittest

class GameStats:
    def __init__(self, name, level, health):
        self.name = name
        self.level = level
        self.health = health

    def calculate_power(self):
        return self.level * 10

    def is_alive(self):
        return self.health > 0

    def damage(self, amount):
        self.health -= amount
        if self.health < 0:
            self.health = 0
        return self.health

    def heal(self, amount):
        self.health += amount
        if self.health > 100:
            self.health = 100
        return self.health

class TestGameStats(unittest.TestCase):
    def setUp(self):
        self.player = GameStats("Aragorn", 15, 100)

    def test_initialization(self):
        self.assertEqual(self.player.name, "Aragorn")
        self.assertEqual(self.player.level, 15)
        self.assertEqual(self.player.health, 100)

    def test_calculate_power(self):
        self.assertEqual(self.player.calculate_power(), 150)

    def test_is_alive(self):
        self.assertTrue(self.player.is_alive())
        self.player.damage(150)
        self.assertFalse(self.player.is_alive())

    def test_damage(self):
        self.player.damage(30)
        self.assertEqual(self.player.health, 70)

    def test_damage_cap(self):
        self.player.damage(150)
        self.assertEqual(self.player.health, 0)

    def test_heal(self):
        self.player.damage(50)
        self.player.heal(20)
        self.assertEqual(self.player.health, 70)

    def test_heal_cap(self):
        self.player.damage(30)
        self.player.heal(50)
        self.assertEqual(self.player.health, 100)

